#!/usr/bin/env bash
#
# Every protobuf contract in this repository has one shape, lives in one kind of module, and is
# generated by the compiler that matches its runtime.
#
#   scripts/check_protos.sh              check the tree
#   scripts/check_protos.sh --list       print every .proto found with its package and methods
#   scripts/check_protos.sh --self-test  check the checker against its own fixtures
#
# WHY THIS EXISTS
#
# The grpc-contract capability says a service's gRPC contract is a <service>-grpc-api module whose
# protos declare package ludwig.<service>.v<N>, java_package ru.ludwigandreas.<service>.grpc.v<N>
# and java_multiple_files = true, and that every rpc states its idempotency_level. Each of those is
# load-bearing somewhere else:
#
#   - the versioned package is what lets v2 be served beside v1;
#   - the java_package pattern is the single JaCoCo and Sonar exclusion for generated code
#     (**/grpc/v*/** in the root POM), so a contract that picks its own package is measured as if
#     somebody had written it by hand;
#   - idempotency_level is what grpc-client-spring-boot-starter reads to decide whether a failed
#     call may be repeated. An rpc that omits it is indistinguishable from one whose author decided
#     it is unsafe, so the option has to be WRITTEN, even when the value is IDEMPOTENCY_UNKNOWN.
#
# It also checks one thing that is not in a .proto at all: that protoc and protoc-gen-grpc-java in
# the root POM are the versions of protobuf-java and grpc-java that ludwig-bom manages. The two
# pairs cannot share a property - a BOM import does not reach a plugin's configuration - and
# generated code from one protobuf line running on another fails at the first message, at runtime.
#
# It is a script rather than a rule in one of the three analysis tools because a .proto is a
# resource file: ArchUnit reads bytecode and cannot see an option that leaves no trace there
# (java_multiple_files, a missing idempotency_level), Checkstyle reads Java source text and is not
# pointed at it, and SonarQube is looking for bugs in code. The enforcement-triad capability names
# gate scripts as the owner for exactly this class of fact, alongside check_migrations.sh.
# scripts/gate.sh runs this, so every change passes through it.
#
# WHY `git ls-files` AND NOT `find`
#
# The protobuf plugin copies sources and unpacks imported protos under target/, so a find-based
# sweep would report build output as a source problem. Unlike check_migrations.sh this lists
# untracked files too (--others --exclude-standard): a contract is usually checked for the first
# time before it has ever been added, and a check that only sees committed files would pass a new
# module exactly once - the time it matters.
#
# WHAT IT DOES NOT CHECK, AND CANNOT
#
#   - that a proto change is wire-compatible with the previous release (needs a baseline
#     descriptor set per release; deferred, see build/architecture-rules/README.md);
#   - that a declared idempotency_level is TRUE. Only the method's author knows.
#
# EXIT CODES:
#   0  the tree conforms (or --list / a passing --self-test)
#   1  at least one violation
#   3  missing prerequisite

set -uo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT" || exit 3

command -v python3 >/dev/null 2>&1 || { printf 'check_protos.sh: python3 is not on PATH\n' >&2; exit 3; }
command -v git >/dev/null 2>&1 || { printf 'check_protos.sh: git is not on PATH\n' >&2; exit 3; }

case "${1:-}" in
  --list|"") ;;
  --self-test) exec python3 scripts/check_protos.py --self-test ;;
  -h|--help) sed -n '3,8p' "${BASH_SOURCE[0]}" | sed 's/^# \{0,1\}//'; exit 0 ;;
  *) printf 'check_protos.sh: unknown option %s\n' "$1" >&2; exit 3 ;;
esac

# scripts/testdata/ is excluded because the --self-test fixtures deliberately violate every rule;
# without the exclusion this check would report its own test data as a problem with the repository.
git ls-files -z --cached --others --exclude-standard -- '*.proto' ':(exclude)scripts/testdata/*' \
  | python3 scripts/check_protos.py "${1:-}"
